 boolean chatOrigin(String url){try{Uri u=Uri.parse(url);return "https".equals(u.getScheme())&&Objects.equals(u.getHost(),Uri.parse(URLS[selected]).getHost())&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 String asset(String name){try(InputStream in=getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}catch(Exception e){return "";}}
 void inject(){if(!chatOrigin(provider.getUrl()))return;provider.evaluateJavascript(asset("provider.js"),v->probe(0));}
 void probe(int attempt){if(!chatOrigin(provider.getUrl())){connected=false;return;}provider.evaluateJavascript("JSON.stringify(window.OSMINOGMobileBridge?.probe()||{})",raw->{JSONObject p=decode(raw);connected=p.optBoolean("ready");emit("connected","ok",connected,"provider",NAMES[selected]);if(!connected&&attempt<20&&foreground)handler.postDelayed(()->probe(attempt+1),500);});}
 static JSONObject decode(String raw){try{Object o=new JSONTokener(raw==null?"null":raw).nextValue();if(o instanceof String)return new JSONObject((String)o);if(o instanceof JSONObject)return(JSONObject)o;}catch(Exception ignored){}return new JSONObject();}
 void emit(String type,Object... values){try{JSONObject o=new JSONObject().put("type",type);for(int i=0;i+1<values.length;i+=2)o.put(String.valueOf(values[i]),values[i+1]);if(port!=null)port.postMessage(new WebMessage(o.toString()));}catch(Exception ignored){}}
 void notice(String text){emit("notice","message",text);}
 void error(String text){String id=currentRequest;currentRequest="";emit("error","id",id,"message",text);}
 void command(JSONObject m)throws Exception{if(!foreground&&!m.optString("type").equals("ready"))return;switch(m.getString("type")){
  case "ready":emit("hello","version","0.1.0");emit("connected","ok",connected,"provider",NAMES[selected]);if(prefs.getBoolean("connectedBefore",false)&&provider.getUrl()==null)provider.loadUrl(prefs.getString("url"+selected,URLS[selected]));break;
  case "connect":chooseProvider();break;
  case "menu":menu();break;
  case "voiceOn":withConsent(()->permission(1));break;
  case "voiceOff":voiceOff();break;
  case "cameraOn":withConsent(()->permission(2));break;
  case "cameraOff":cameraOff();break;
  case "cameraLayout":if(camera||eye.running){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(dp((float)Math.max(1,Math.min(1500,m.optDouble("w",1)))),dp((float)Math.max(1,Math.min(1000,m.optDouble("h",1)))));p.leftMargin=dp((float)Math.max(0,m.optDouble("x")));p.topMargin=dp((float)Math.max(0,m.optDouble("y")));preview.setLayoutParams(p);preview.setVisibility(m.optBoolean("visible",true)?View.VISIBLE:View.INVISIBLE);}break;
  case "flip":front=!front;if(camera){camera=false;eye.start(front);}break;
  case "ask":ask(m);break;
  case "speak":speak(m.optString("text"));break;
  case "continueVoice":listenLater(500);break;
  case "interrupt":if(tts!=null)tts.stop();speaking=false;listenLater(100);break;
  case "stop":stopSession();break;
  default:break;
 }}
 void chooseProvider(){stopSession();emit("paused");new AlertDialog.Builder(this).setTitle("Подключить свой ИИ").setItems(NAMES,(d,index)->{selected=index;prefs.edit().putInt("provider",selected).apply();connected=false;String url=prefs.getString("url"+selected,URLS[selected]);if(!chatOrigin(url))url=URLS[selected];provider.loadUrl(url);shell.setVisibility(View.GONE);preview.setVisibility(View.GONE);new AlertDialog.Builder(this).setMessage("Войди в свой аккаунт на сайте "+NAMES[selected]+", открой чат и нажми «Готово». Пароль вводится только на сайте сервиса. API-ключ не нужен. Если сервис запрещает вход во встроенном браузере, подключение здесь будет недоступно — приложение не обходит этот запрет.").setPositiveButton("Понятно",null).show();}).setNegativeButton("Отмена",null).show();}
 void returnToShell(){shell.setVisibility(View.VISIBLE);if(chatOrigin(provider.getUrl())){prefs.edit().putBoolean("connectedBefore",true).apply();inject();}else{connected=false;emit("connected","ok",false,"provider",NAMES[selected],"message","Заверши вход и открой чат на сайте сервиса.");}}
 void menu(){new AlertDialog.Builder(this).setTitle("OSMINOG Vision · 0.1.0").setItems(new String[]{"Открыть подключённый чат","Обновить онлайн","Очистить историю на устройстве","Как работает зрение"},(d,i)->{if(i==0){stopSession();emit("paused");if(provider.getUrl()==null)chooseProvider();else shell.setVisibility(View.GONE);}if(i==1){stopSession();emit("paused");updater.check();}if(i==2)new AlertDialog.Builder(this).setMessage("Удалить локальную переписку? История на стороне ИИ-сервиса не удаляется.").setPositiveButton("Удалить",(x,y)->emit("clear")).setNegativeButton("Отмена",null).show();if(i==3)new AlertDialog.Builder(this).setMessage("Это веб-чат твоего ИИ с голосом Android. Камера работает только в открытом приложении. При каждом вопросе с включённой камерой в чат прикрепляется свежий кадр. Это не непрерывная видеотрансляция модели. Кадры и звук приложение не записывает. ИИ-провайдер получает отправленные тексты и кадры; распознавание и синтез речи Android могут использовать интернет. Сайты ИИ могут менять интерфейс и ограничивать загрузку изображений.").setPositiveButton("Понятно",null).show();}).show();}
 void withConsent(Runnable action){if(!connected){chooseProvider();return;}if(prefs.getBoolean("mediaConsent1",false)){action.run();return;}new AlertDialog.Builder(this).setTitle("Голос и зрение").setMessage("Во время сеанса твои вопросы и кадры камеры отправляются выбранному ИИ через твой аккаунт. Android распознаёт и озвучивает речь; его речевой сервис может использовать интернет. Видео и звук не записываем. При сворачивании камера и микрофон отключаются.").setPositiveButton("Начать",(d,i)->{prefs.edit().putBoolean("mediaConsent1",true).apply();action.run();}).setNegativeButton("Не сейчас",null).show();}
 void permission(int action){String name=action==1?Manifest.permission.RECORD_AUDIO:Manifest.permission.CAMERA;if(checkSelfPermission(name)==PackageManager.PERMISSION_GRANTED){if(action==1)voiceOn();else cameraOn();return;}if(permissionAction!=0)return;permissionAction=action;requestPermissions(new String[]{name},action);}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);permissionAction=0;if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED){if(!foreground){resumeAction=request;return;}if(request==1)voiceOn();if(request==2)cameraOn();}else notice(request==1?"Микрофон не разрешён. Можно писать текстом.":"Камера не разрешена. Голосовой и текстовый чат доступны.");}
 void cameraOn(){if(!foreground)return;camera=true;preview.setVisibility(View.VISIBLE);emit("camera","on",true);eye.start(front);}
 void cameraOff(){camera=false;eye.close();preview.setVisibility(View.GONE);emit("camera","on",false);}
 void voiceOn(){if(!foreground)return;if(!SpeechRecognizer.isRecognitionAvailable(this)){notice("На устройстве нет службы распознавания речи. Установи/включи речевую службу Android или пиши текстом.");return;}voice=true;voiceErrors=0;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);emit("voice","on",true);listenLater(100);}
 void voiceOff(){voice=false;listening=false;if(recognizer!=null){recognizer.cancel();recognizer.destroy();recognizer=null;}if(tts!=null)tts.stop();speaking=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);emit("voice","on",false);}
 void listenLater(long delay){final int e=epoch;handler.postDelayed(()->{if(e==epoch&&foreground&&voice&&!speaking&&currentRequest.isEmpty()&&!listening)listen();},delay);}
 void listen(){if(!foreground||!voice||speaking||!currentRequest.isEmpty()||listening)return;try{if(recognizer==null){recognizer=Build.VERSION.SDK_INT>=31&&SpeechRecognizer.isOnDeviceRecognitionAvailable(this)?SpeechRecognizer.createOnDeviceSpeechRecognizer(this):SpeechRecognizer.createSpeechRecognizer(this);recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){emit("listening");}public void onBeginningOfSpeech(){}public void onRmsChanged(float rms){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){listening=false;}public void onError(int code){listening=false;if(!voice||!foreground||!currentRequest.isEmpty()||speaking)return;if(code==SpeechRecognizer.ERROR_NO_MATCH||code==SpeechRecognizer.ERROR_SPEECH_TIMEOUT){listenLater(1000);return;}if(++voiceErrors>2){voiceOff();notice("Речевой сервис не отвечает. Проверь язык и интернет; затем включи разговор снова.");}else listenLater(1800);}public void onResults(Bundle b){listening=false;ArrayList<String> text=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);if(!voice||!foreground||speaking||!currentRequest.isEmpty())return;voiceErrors=0;if(text!=null&&!text.isEmpty()&&!text.get(0).trim().isEmpty())emit("speech","text",text.get(0));else listenLater(500);}public void onPartialResults(Bundle b){}public void onEvent(int t,Bundle b){}});}
  Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"ru-RU").putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false).putExtra(RecognizerIntent.EXTRA_MAX_RESULTS,1).putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,true);listening=true;recognizer.startListening(i);
 }catch(Exception e){listening=false;voiceOff();notice("Не удалось включить распознавание речи.");}}
 void speak(String text){if(!voice||!foreground||text.isEmpty())return;if(!ttsReady){notice("Нет русского голоса Android. Включи его в настройках синтеза речи. Ответ доступен текстом.");listenLater(1200);return;}if(recognizer!=null)recognizer.cancel();listening=false;speaking=true;emit("speaking");String plain=text.replaceAll("https?://\\S+","").replaceAll("[#*_`]+","");int limit=Math.min(3500,TextToSpeech.getMaxSpeechInputLength()-1);plain=plain.substring(0,Math.min(limit,plain.length()));if(tts.speak(plain,TextToSpeech.QUEUE_FLUSH,null,"osminog-"+System.currentTimeMillis())==TextToSpeech.ERROR){speaking=false;notice("Не удалось озвучить ответ.");listenLater(1200);}}
 void ask(JSONObject m){if(!currentRequest.isEmpty())return;if(!connected||!chatOrigin(provider.getUrl())){emit("error","id",m.optString("id"),"message","Сначала подключи ИИ-чат.");return;}String text=m.optString("text").trim(),id=m.optString("id");if(text.isEmpty()||text.length()>12000||!id.matches("m-[0-9]+"))return;currentRequest=id;partial="";frameSent=false;if(recognizer!=null)recognizer.cancel();listening=false;if(tts!=null)tts.stop();speaking=false;int gen=epoch;
  if(m.optBoolean("withCamera")){if(!camera){error("Камера выключена; вопрос с изображением не отправлен.");return;}eye.frame((image,problem)->{if(gen!=epoch||!id.equals(currentRequest))return;if(problem!=null){error(problem);return;}sendAsk(id,text,image);});}else sendAsk(id,text,"");}
 void sendAsk(String id,String text,String image){if(!foreground||!id.equals(currentRequest))return;try{String prompt="[OSMINOG:"+id+"]\nТы собеседник в OSMINOG. Отвечай естественно, по-русски, без повторения этой инструкции и технического маркера. Не называй личности людей по изображению. "+(image.isEmpty()?"К этому сообщению кадр НЕ приложен; не утверждай, что видишь происходящее.":"К вопросу приложен свежий кадр камеры; отвечай только по тому, что действительно видно. Не выдумывай детали.")+"\nВопрос: "+text;JSONObject q=new JSONObject().put("id",id).put("text",prompt).put("image",image);provider.evaluateJavascript("Boolean(window.OSMINOGMobileBridge?.start("+q.toString()+"))",raw->{if(!id.equals(currentRequest))return;if(!"true".equals(raw)){error("Чат не готов принять запрос. Открой подключённый сервис.");return;}poll(id,epoch,System.currentTimeMillis());});}catch(Exception e){error("Не удалось передать вопрос.");}}
 void poll(String id,int gen,long started){if(gen!=epoch||!id.equals(currentRequest)||!foreground)return;if(System.currentTimeMillis()-started>180000){error("Превышено время ожидания ИИ.");return;}provider.evaluateJavascript("JSON.stringify(window.OSMINOGMobileBridge?.snapshot()||{})",raw->{if(gen!=epoch||!id.equals(currentRequest))return;JSONObject r=decode(raw);if(!id.equals(r.optString("id"))){error("Подключённый чат перезагрузился. Открой его и повтори вопрос.");return;}if(r.optBoolean("frameAccepted")&&!frameSent){frameSent=true;emit("frameSent","id",id);}String state=r.optString("state"),text=r.optString("text");if("error".equals(state)){error(r.optString("error","Ошибка ИИ-сервиса"));return;}if("done".equals(state)){currentRequest="";emit("answer","id",id,"text",text);return;}if(!text.equals(partial)&&!text.isEmpty()){partial=text;emit("partial","id",id,"text",text);}handler.postDelayed(()->poll(id,gen,started),600);});}
 void stopSession(){epoch++;currentRequest="";voiceOff();cameraOff();if(provider!=null&&chatOrigin(provider.getUrl()))provider.evaluateJavascript("window.OSMINOGMobileBridge?.cancel()",null);}
 @Override protected void onResume(){super.onResume();foreground=true;if(resumeAction!=0){int action=resumeAction;resumeAction=0;if(action==1)voiceOn();else cameraOn();}if(updater!=null)updater.resume();}
 @Override protected void onPause(){foreground=false;stopSession();emit("paused");CookieManager.getInstance().flush();super.onPause();}
 @Override public void onBackPressed(){if(shell.getVisibility()!=View.VISIBLE){returnToShell();return;}if(voice||camera||!currentRequest.isEmpty()){stopSession();emit("paused");return;}super.onBackPressed();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==50&&fileCallback!=null){fileCallback.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);fileCallback=null;}}
 @Override protected void onDestroy(){stopSession();handler.removeCallbacksAndMessages(null);if(updater!=null)updater.close();if(tts!=null)tts.shutdown();if(fileCallback!=null)fileCallback.onReceiveValue(null);if(port!=null)port.close();root.removeAllViews();shell.destroy();provider.destroy();super.onDestroy();}
